import {el} from '../view.mjs';
import {browserProductionStore} from './production.mjs';
import {buildStatuses,qcResults,qcDefinition,validateQC} from './qc-model.mjs';
export function mountQC(root,context){
 const store=browserProductionStore(),saved=store.get(context).qc||{},definition=qcDefinition(context),section=el('section',null,'sheet-section qc-section'),form=el('form',null,'production-form'),fields={};section.append(el('h2','Build & QC'),el('p','Internal production record for this kit unit. Saving does not change order status or stock.','sheet-note'));
 function field(key,label,type='text',options=null){const wrap=el('label',label),input=el(options?'select':type==='textarea'?'textarea':'input');if(options)for(const v of options){const o=el('option',v);o.value=v;input.append(o);}else if(type!=='textarea')input.type=type;input.value=saved[key]??options?.[0]??'';wrap.append(input);fields[key]=input;form.append(wrap);return input;}
 field('builder','Built by');field('buildDate','Build date','date');field('status','Build status','select',buildStatuses);
 const checkGroup=el('fieldset'),legend=el('legend','Component & assembly checks');checkGroup.append(legend);const checks={};for(const [id,label] of definition.checks){const wrap=el('label',null,'qc-check'),input=el('input');input.type='checkbox';input.checked=!!saved.checks?.[id];checks[id]=input;wrap.append(input,document.createTextNode(label));checkGroup.append(wrap);}form.append(checkGroup);
 const measurements={};if(definition.measurements.length){const group=el('fieldset');group.append(el('legend','Measured values (optional)'));for(const m of definition.measurements){const wrap=el('label',m.label+' / '+m.unit),input=el('input');input.type='number';input.min='0';input.step='any';input.value=saved.measurements?.[m.id]??'';measurements[m.id]=input;wrap.append(input);group.append(wrap);}form.append(group);}
 field('result','Final QC result','select',qcResults);field('person','QC by');field('date','QC date','date');field('notes','QC notes','textarea');const save=el('button','Save Build & QC','admin-button'),message=el('p');message.setAttribute('role','status');form.append(save,message);let dirty=false;form.addEventListener('input',()=>{dirty=true;form.dataset.dirty='true';message.textContent='Unsaved Build & QC changes.';});window.addEventListener('beforeunload',e=>{if(dirty){e.preventDefault();e.returnValue='';}});
 form.addEventListener('submit',async e=>{e.preventDefault();save.disabled=true;try{const value=validateQC({...Object.fromEntries(Object.entries(fields).map(([k,i])=>[k,i.value])),checks:Object.fromEntries(Object.entries(checks).map(([k,i])=>[k,i.checked])),measurements:Object.fromEntries(Object.entries(measurements).map(([k,i])=>[k,i.value]))},definition);await store.update(context,r=>{r.qc=value;});dirty=false;form.dataset.dirty='false';message.textContent='Build & QC saved.';}catch(error){message.textContent=error.message;}finally{save.disabled=false;}});section.append(form);root.append(section);
}
